  if (c.list.length === 1) { chooseInst(c.list[0], false); return; }
  selected = { list: c.list.slice().sort((a, b) => b.n - a.n), inst: null };
  const lat = c.list.reduce((a, s) => a + s.lat, 0) / c.list.length, lon = c.list.reduce((a, s) => a + s.lon, 0) / c.list.length;
  flyTo(lon, lat, min(MAX_ZOOM, cam.zoom * 2.4), 800);
