function showDetail() {
  if (document.getElementById("globe-wrap").classList.contains("narrow")) { detailEl.scrollIntoView({ block: "nearest", behavior: "smooth" }); }
  else { panel.elt.scrollTo({ top: max(0, detailEl.offsetTop - 8), behavior: "smooth" }); }
}